<script setup lang="ts">import {Cohort} from '../types/domain';defineProps<{cohorts:Cohort[];modelValue:number;label:string}>();defineEmits<{"update:modelValue":[value:number]}>()</script><template><label>{{label}}<select :aria-label="label" :value="modelValue" @change="$emit('update:modelValue',Number(($event.target as HTMLSelectElement).value))"><option :value="0">选择试验批次</option><option v-for="c in cohorts" :key="c.id" :value="c.id">{{c.code}} / {{c.name}} · {{c.specimen_count}} 件</option></select></label></template>
